{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Efficacy and effectiveness of COVID-19 vaccines against SARS-CoV-2 infection: interim results of a living systematic review, 1 January to 14 May 2021",
      "reason": "The title explicitly includes the phrase \"living systematic review,\" identifying the report as a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "Efficacy and effectiveness of COVID-19 vaccines against SARS-CoV-2 infection: interim results of a living systematic review",
      "reason": "The title clearly states the main objective/question (efficacy and effectiveness of COVID-19 vaccines) and the outcome/condition (against SARS-CoV-2 infection)."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_0",
      "quote": "interim results of a living systematic review, 1 January to 14 May 2021",
      "reason": "The title provides supplementary information indicating that it is a \"living\" systematic review and specifies the time period covered by the interim results."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "All vaccines approved by the European Medical Agency (EMA) at the time of writing demonstrated high vaccine efficacy/effectiveness (VE) against severe COVID-19. With vaccination programmes being implemented in most European countries, it becomes urgent to assess the extent to which these vaccines are also able to prevent symptomatic and asymptomatic infections",
      "reason": "The text describes the current state of knowledge (vaccines are effective against severe disease) and the uncertainty (effectiveness against infection/transmission)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "With vaccination programmes being implemented in most European countries, it becomes urgent to assess the extent to which these vaccines are also able to prevent symptomatic and asymptomatic infections to guide public health recommendations and develop strategies for fully vaccinated people.",
      "reason": "The text explicitly states the need for the review to guide public health recommendations."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not mention the existence of similar systematic reviews, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review evaluates the effects of an intervention (COVID-19 vaccines), but does not describe the proposed mechanism of action of the intervention."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not focus on complex interventions or delivery contexts requiring a logic model."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "In detail, we report the interim results of the review focusing on two research questions: What is the efficacy/effectiveness of COVID-19 vaccines in preventing SARS-CoV-2 infections (irrespective of whether they were symptomatic or not), and what is the efficacy/effectiveness of COVID-19 vaccines in preventing asymptomatic SARS-CoV-2 infection?",
      "reason": "The manuscript explicitly states the research questions addressed by the review."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "We considered studies of any design as long as they had a comparison group that investigated VE against SARS-CoV-2 infection and/or asymptomatic SARS-CoV-2 infection after vaccination with an EMA-approved COVID-19 vaccine (see Supplement Part S2 for complete population intervention comparison outcomes (PICO) questions).",
      "reason": "The review explicitly references the PICO framework for its planned comparisons regarding vaccine efficacy/effectiveness."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "We considered studies of any design as long as they had a comparison group that investigated VE against SARS-CoV-2 infection and/or asymptomatic SARS-CoV-2 infection after vaccination with an EMA-approved COVID-19 vaccine",
      "reason": "The manuscript specifies the inclusion criteria regarding study design (any design with a comparison group), the intervention (EMA-approved COVID-19 vaccines), and the outcomes (VE against SARS-CoV-2 infection and/or asymptomatic SARS-CoV-2 infection)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "No restrictions were made regarding publication language or status.",
      "reason": "The manuscript explicitly states that there were no restrictions on publication language or status."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not distinguish between studies excluded because the outcome was not measured versus studies excluded because the outcome results were not reported. The flowchart (Figure 1) only provides a generic 'no relevant data' category for exclusions."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "In 12 studies, the effectiveness of Comirnaty (BionTech, Mainz, Germany/Pfizer, Puurs, Belgium) was evaluated. Two studies investigated COVID-19 Vaccine Janssen (Janssen-Cilag International, Beerse, Belgium), one study studied Vaxzevria (AstraZeneca/Oxford, Oxford, United Kingdom (UK)), and 11 studies investigated more than one vaccine.",
      "reason": "The manuscript specifies how studies were grouped for synthesis, specifically by vaccine type, dose (one-dose vs. two-dose), and infection type (symptomatic vs. asymptomatic), which aligns with the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Vaccination against severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2) infection plays a key role in the containment of the coronavirus disease (COVID19) pandemic. All vaccines approved by the European Medical Agency (EMA) at the time of writing demonstrated high vaccine efficacy/effectiveness (VE) against severe COVID-19. With vaccination programmes being implemented in most European countries, it becomes urgent to assess the extent to which these vaccines are also able to prevent symptomatic and asymptomatic infections to guide public health recommendations",
      "reason": "The manuscript provides a rationale for the restriction to EMA-approved vaccines, linking it to the context of vaccination programs in European countries and the need to guide public health recommendations."
    }
  ],
  "confidence": 100
}

